-- Replace Mindat-derived positions and Mindat-sourced notes on occurrences (25 Nov 2026).
-- Backup: licence_hold.occ_mindat_positions_bak_20261125 (full rows before the change).
-- Rollback: UPDATE core.occurrences o SET geom = b.geom, comments = b.comments, position_accuracy = b.position_accuracy,
--   modified_by = b.modified_by, modified_date = b.modified_date FROM licence_hold.occ_mindat_positions_bak_20261125 b WHERE o.occurrence_id = b.occurrence_id;
BEGIN;
CREATE TABLE licence_hold.occ_mindat_positions_bak_20261125 AS SELECT * FROM core.occurrences WHERE occurrence_id IN (3734,3737,3739,3740,3741,3742,3746,3747,3748,3752,3753,3754,3755,3759,3760,3762,3772,3827);
UPDATE core.occurrences SET comments = $c$30-year mining licence awarded by Government of Greenland 2016; early site works commenced 2018. 2017 Feasibility Study: ~14-year mine life, 3.3 Mtpa throughput, potential >200,000 t/yr zinc metal output. Ownership history: Ironbark Zinc -> sold interests to Almeera Ventures Limited (Dubai) for US$900,000 (Dec 2024) -> Skylark Minerals relinquished the licence and wound up operations 30-Dec-2025 (exact relationship between Almeera Ventures and Skylark Minerals unclear from source). STATUS FLAG: as of the source's most recent information (Dec 2025), the licence has been relinquished and no current licence holder/operator is confirmed - status kept as EXPLORATION (never reached production) but tenure status should be re-verified. Source: user-supplied Wikipedia summary (en.wikipedia.org/wiki/Citronen_mine). Not independently cross-checked; coordinates as given (83 00'N 29 55'W).$c$, modified_by = 'mindat_cleanup_20261125', modified_date = now() WHERE occurrence_id = 3734;
UPDATE core.occurrences SET comments = $c$Proposed open-pit mine, never reached production. History: London Mining Inc. announced construction 2011, targeting 2015 start; development stalled April 2013 on falling iron ore prices; Oct 2013 exploitation licence signed with Greenland Government; London Mining filed bankruptcy Oct 2014; Chinese conglomerate General Nice acquired mining rights Jan 2015; Greenland Government revoked General Nice's licence Nov 2021 for prolonged inactivity and unpaid fees. Planned production ~15 Mtpa ore; planned capex at least US$2.35 billion; 105km slurry pipeline planned to a year-round ice-free port at Taseraarssuk Bay. No current licence holder as of source date. Source: user-supplied Wikipedia summary (en.wikipedia.org/wiki/Isua_Iron_Mine), citing Nunatsiaq News, Financial Times, Reuters, Mining Technology, Naalakkersuisut (Greenland Government). Not independently cross-checked; coordinates as given (65 30'N 50 20'W).
STRUCTURED RESOURCE LOADED (2026-10-07): core.resource_estimates holds the January 2006 IMC Group Consultants JORC Indicated+Inferred resource of 955 Mt at 34% Fe, of which 181 Mt at 33.43% Fe is an open-pit Indicated+Inferred resource, as quoted in GEUS Fact Sheet 16 (2008, Banded iron formation, data.geus.dk/pure-pdf/2008_Fact_Sheet_16_Banded_iron_formation.pdf; not in the document library, so source_document_id is blank). This is a 20-year-old estimate under the earlier London Mining concession. The Cryolite Company estimate of about 2 billion tonnes at 32.9% Fe from the 1960s is not JORC-compliant and is not loaded.$c$, modified_by = 'mindat_cleanup_20261125', modified_date = now() WHERE occurrence_id = 3737;
UPDATE core.occurrences SET comments = $c$Niaqornakassak, West Greenland. Paleoproterozoic carbonatite. NAME FLAG: source document spells this "Niaqornakassak"; the first load matched it to "Niaqornaarsuk peninsula", a known carbonatite-bearing locality in Kujalleq, South Greenland, as the closest plausible identification (medium confidence, not a confirmed exact match).
LOCATION CORRECTED (2026-10-09): the original point (60.54 N, 45.10 W, Niaqornaarsuk peninsula, South Greenland) was a name-match guess and was about 1,300 km from the site. Table 1 of Jonsson et al. (Critical metals and minerals in the Nordic countries of Europe; library doc 74), compiled from national databases and Eilu et al. (2021), lists Niaqornakassak as a Paleoproterozoic REE carbonatite at 71.67 N, 52.78 W (West Greenland, Uummannaq area), which matches this record's own description (West Greenland, Paleoproterozoic carbonatite). Point now at those coordinates (2 decimals, roughly +/-1 km, deposit-level). Record renamed from "Niaqornaarsuk peninsula (Niaqornakassak)". RESOURCE LOADED: 26.00 Mt with 304,000 t REE as listed in Table 1 (regional compilation, category and reporting standard not stated, no grade or date). The NAME FLAG above no longer applies. Rollback: core.occurrences_nordic_bak_20261009.$c$, modified_by = 'mindat_cleanup_20261125', modified_date = now() WHERE occurrence_id = 3739;
UPDATE core.occurrences SET comments = $c$Stub-level source: no discovery date, exploration history, current operator, or precise resource date available. Estimated reserves 3.5 Mt ore @ 0.5% Nb (date/source company not specified in the Wikipedia article itself; article cites Commerce Resources Corp "Tantalum reserves in Canada" PDF 2013, Mindat.org, and Mineralienatlas.de as its own references, but does not attribute the 3.5Mt/0.5% figure to a specific one of these). Source: user-supplied Wikipedia summary (en.wikipedia.org/wiki/Qaqqaarsuk_deposit). Not independently cross-checked; coordinates as given (65 23'00"N 51 40'00"W).
COMMODITY UPDATE (2026-10-06): P added per the GEUS Greenland Geology and Raw Material Deposits map label (Nb, P). Map-derived, no quantities loaded.$c$, modified_by = 'mindat_cleanup_20261125', modified_date = now() WHERE occurrence_id = 3740;
UPDATE core.occurrences SET geom = ST_SetSRID(ST_MakePoint(-44.94, 61.2), 4326), position_accuracy = NULL, comments = $c$Motzfeldt, Igaliku Complex, South Greenland. Mesoproterozoic Gardar Province. REE and Ta reported on a 340 Mt ore basis; Nb reported on a separate 500 Mt ore basis (different resource estimate).
COMMODITY UPDATE (2026-10-06): Zr added per the GEUS Greenland Geology and Raw Material Deposits map label (Ta, REE, Zr, (Nb)). Map-derived, no quantities loaded.
RESOURCE LOADED (2026-10-09): Nb 500 Mt with 450,000 t Nb; REE 340 Mt with 760,240 t REE; Ta 340 Mt with 33,000 t Ta, as listed in Table 1 of Jonsson et al. (library doc 74), a regional compilation from national databases and Eilu et al. (2021). Resource category, reporting standard, grades and dates are not stated, the figures are not classified resources, and the three commodities are different mineralised zones of the Motzfeldt centre that overlap, so the tonnages must not be added. Coordinates in Table 1 (61.20 N, 44.94 W) agree with this record. is_deposit set to true because Table 1 lists it as a deposit.
LOCATION (2026-11-25): point moved to the coordinates in Table 1 of Jonsson et al. (library doc 74): 61.20 N, 44.94 W (centre-level, 2 decimals). The earlier sub-zone proxy point came from Mindat and was replaced.$c$, modified_by = 'mindat_cleanup_20261125', modified_date = now() WHERE occurrence_id = 3741;
UPDATE core.occurrences SET comments = $c$Kuannersuit / Kvanefjeld (Main Zone + Sorensen + Zone 3), Ilimaussaq complex, South Greenland. Mesoproterozoic. Dominated by lujavrites. REE, U and Th predominantly hosted in steenstrupine (source: steenstrupine assays >=1.5 wt% REE and >=400 ppm U3O8 - mineral-level assay, not included as deposit bulk grade). Originally explored for uranium (1956-1984), resumed for REE in 2007. STATUS FLAG: challenged by a Greenlandic law banning mining of ores with more than 100 ppm uranium, passed November 2021 - project development is currently blocked by this legislation, deposit_status kept as EXPLORATION (not formally cancelled) but this should be reviewed. UPDATE (2026-09-23, from Energy Transition Minerals Ltd (ASX:ETM, formerly Greenland Minerals Ltd) investor presentation dated 19 January 2026): Full Measured/Indicated/Inferred classification breakdown now loaded (previously only a blended Grand Total was recorded) - Measured 143 Mt, Indicated 308 Mt, Inferred 559 Mt, Grand Total 1010 Mt, all at 150 ppm U3O8 cutoff. Two new by-product commodities added: U3O8 (592.84 million lbs contained, 266 ppm grade) and Zn (2.42 Mt contained, 2,397 ppm/0.24% grade). DATA CROSS-CHECK: this presentation's own summary slide (slide 10) states "1.14Mt of contained REO", which is very likely a typo (missing a leading digit) - the detailed resource table in the same document's appendix gives Grand Total contained TREO as 11.14 Mt, matching the figure already in this database from the Greenland occurrences document. The 11.14 Mt figure is used here. LITIGATION UPDATE: Greenland Minerals A/S (GMAS, ETM subsidiary and exploration licence holder) is in arbitration before an ad hoc tribunal in Copenhagen and litigation in the courts of Greenland and Denmark, seeking confirmation of its entitlement to an exploitation licence under Greenland's Minerals Act, following the Government's refusal citing the 2021 Uranium Act. GMAS applied 30 September 2025 to extend exploration licence MEL 2010-02 to 31 December 2028. ETM asserts the only known BULK occurrence of steenstrupine globally is at Kvanefjeld, offering non-refractory, lower-cost processing relative to typical REE deposits.
COMMODITY UPDATE (2026-10-06): Li, F and Be added as SECONDARY per the GEUS Greenland Geology and Raw Material Deposits map label (REE, (Li, F, Be)). The map also names Soerensen and Zone 3 as part of the same Ilimaussaq-complex REE area; they are not separate rows here.
STRUCTURED RESOURCE LOADED (2026-10-07): core.resource_estimates now holds the full JORC table (Measured 143 Mt, Indicated 308 Mt, Inferred 559 Mt, total 1,010 Mt; 150 ppm U3O8 cut-off) for TREO, HREO, Y2O3, U3O8 and Zn with grades and contained metal (total contained TREO 11.14 Mt), read from slide 23 of the ETM investor presentation (doc 6; the table is an image). The estimate is the one announced to the ASX on 12 February 2015 (per slide 10), so it is an old estimate; its effective date and competent person are not shown in the presentation and are left blank. Measured and Indicated TREO grades (12,100 and 11,100 ppm) agree with the SDSG inventory (doc 55). The ETM slide 10 text of 1.14 Mt contained REO is a typo for 11.14 Mt. LREO and lanthanide-only REO columns are not loaded. The SDSG figure of 108 Mt at 1.43% TREO described as reserves from the 2019 feasibility study is NOT loaded because SDSG wording is ambiguous about whether it is a reserve or a resource.
DEPOSIT FLAG (2026-10-07): is_deposit changed from false to true because a JORC / S-K 1300 mineral resource estimate is now loaded for this occurrence in core.resource_estimates.$c$, modified_by = 'mindat_cleanup_20261125', modified_date = now() WHERE occurrence_id = 3742;
UPDATE core.occurrences SET geom = ST_SetSRID(ST_MakePoint(-32.18333, 67.85), 4326), position_accuracy = 'AREA_CENTROID', comments = $c$Kap Edvard Holm, East Greenland. Mafic-ultramafic PGM occurrence, listed alongside Kruse Fjord intrusions and Mikis Fjord Macrodyke in the source document (those two are not loaded). No quantified resource reported. Exploration history: in 1990 Danish media reported a "multi-billion-dollar" gold deposit near Kap Edvard Holm, described at the time as the world's largest - this is a media claim, NOT a compliant resource/reserve estimate, and no tonnage or grade figures are available from any source seen so far; not loaded as a quantified resource. The Geological Survey of Denmark and Greenland (GEUS) conducted field exploration in 2009 (helicopter reconnaissance, rock-chip sampling). Historic explorer: Platinova.
LOCATION (2026-11-25): point is the GeoNames position of the cape Kap Edvard Holm (67.85 N, 32.183 W, GeoNames 3423980, CC BY 4.0); the intrusive complex lies around the cape, so treat as +/-5 km. The earlier point and a mineral list came from Mindat and were removed.$c$, modified_by = 'mindat_cleanup_20261125', modified_date = now() WHERE occurrence_id = 3746;
UPDATE core.occurrences SET comments = $c$Fiskenaesset, West Greenland. Anorthosite complex, mafic-ultramafic PGM occurrence, listed alongside Amikoq and Maniitsoq in the source document. Matched to the modern Greenlandic place name Qeqertarsuatsiaat. No quantified resource reported.
COORDINATE FLAG (2026-10-06): no PGM-specific point exists in the source. The stored point is the Qeqertarsuatsiaat settlement (63.089N, 50.678W) and is IDENTICAL to row 3753 (Aappaluttoq), so treat it as locality-level only. The Fiskenaesset anorthosite complex has a strike length of about 200 km (GEUS), and PGE-bearing horizons such as the Ghisler Reef are located within it. The GEUS Greenland Geology and Raw Material Deposits map labels Fiskenaesset / Qeqertarsuatsiaat for CHROMIUM, and Cr has now been added to this row on that basis (map-derived, no quantities).$c$, modified_by = 'mindat_cleanup_20261125', modified_date = now() WHERE occurrence_id = 3747;
UPDATE core.occurrences SET geom = ST_SetSRID(ST_MakePoint(-52.89822, 65.41506), 4326), position_accuracy = 'TOWN_CENTROID', comments = $c$Maniitsoq, West Greenland. Mafic-ultramafic PGM occurrence, listed alongside Amikoq and Fiskenaesset in the source document. LOCATION (2026-11-25): no occurrence-level point is published; the point is Maniitsoq town (65.415 N, 52.898 W, GeoNames 3421982, CC BY 4.0), a town-level proxy with low precision. The earlier point came from Mindat and was replaced. No quantified resource reported.$c$, modified_by = 'mindat_cleanup_20261125', modified_date = now() WHERE occurrence_id = 3748;
UPDATE core.occurrences SET geom = ST_SetSRID(ST_MakePoint(-52.46667, 65.5), 4326), position_accuracy = 'AREA_CENTROID', comments = $c$High-temperature metamorphic event ~2.85-2.70 Ga (Neoarchean); recent studies also indicate fluid movement at ~2.6-2.5 Ga, possibly related to terminal orogenesis and North Atlantic Craton assembly - exact timing of corundum growth is debated, both events may have contributed. Associated minerals: amphiboles, biotite, calcite, apatite and other metamorphic phases. Distinct locality from the separately-recorded Maniitsoq PGM occurrence (~35km away, different deposit). Of scientific interest for Neoarchean metamorphism/fluid-rock interaction studies; potentially valuable for gemstone production but no resource/reserve figures or exploration/mining history are given in the source. Source: user-supplied text citing Wikipedia (Maniitsoq).
LOCATION (2026-11-25): GEUS Report 2014/72 (Appel and Ghisler, Ruby- and sapphirine-bearing mineral occurrences in the Fiskenaesset, Nuuk and Maniitsoq regions, appendix) names this the Kangerdluarssuk ruby locality (Maniitsoq 1) and shows it only on a map. The point is the Kangerluarsuk fjord east of Maniitsoq (65.50 N, 52.467 W, GeoNames 3422626, CC BY 4.0), so treat as +/-10 km. The earlier point came from Mindat and was replaced.$c$, modified_by = 'mindat_cleanup_20261125', modified_date = now() WHERE occurrence_id = 3752;
UPDATE core.occurrences SET comments = $c$Pink sapphire and ruby (corundum gem varieties) deposit. Developed by True North Gems Greenland (a Canadian firm's Greenland subsidiary). STATUS FLAG: source (Wikipedia, citing a New York Times article by Saskia de Rothschild, 6 Sept 2015) describes the mine as "under development" employing ~30 people, as of 2015 - this is a dated snapshot; the operator/ownership and production status should be re-verified against a current source (note: the operating entity may have since changed, e.g. to "Greenland Ruby" - not confirmed from this source, flagged for follow-up, not asserted). No tonnage, grade, or reserve/resource figures given in the source. COORDINATE FLAG: no deposit-specific coordinate was given in the source; the coordinate used here is that of the nearby settlement of Qeqertarsuatsiaat itself (63.08889N 50.67778W), so treat as approximate/locality-level only, not a surveyed deposit point. Source: user-supplied Wikipedia summary (en.wikipedia.org/wiki/Qeqertarsuatsiaat).$c$, modified_by = 'mindat_cleanup_20261125', modified_date = now() WHERE occurrence_id = 3753;
UPDATE core.occurrences SET comments = $c$Developer: Hudson Greenland (subsidiary of Hudson Resources Inc.). Timeline: PFS Apr 2013-Jul 2014; PEA completed March 2015 (NPV ~US$205M); 30-year exploitation licence granted Sep 2015 (extendable +20yr); mine life estimated >100 years; construction 2016-Nov 2018; commissioning Feb 2019. Forecast production 200,000 tpa initially, rising to 500,000 tpa. Conventional open-pit (Sandvik DX800 drill, Hyundai HL980 loader), mobile crushing (3 phases for e-glass/filler/coatings feed), magnetic separation at port-area processing plant, 11km haul road to port at Sondre Stromfjord (Kangerlussuaq). 10-year binding offtake agreement (Jul 2015) with a North American materials company; May 2016 LoI with Metro Ports for a dedicated port/storage/bagging facility adjacent to Port of Savannah, USA. Financing: C$10.9M equity (Feb 2017); US$4M private placement from Greenland Venture (Mar 2017, Greenland Government investment vehicle); US$22.5M debt from Cordiant Capital to Hudson Greenland (Jul 2017: C$17.3M senior + C$12.7M subordinated), senior loan later assumed by the European Investment Bank (Feb 2017). Power: diesel generators (750kW processing/camp, 25kW quarry). Water from adjacent lake via insulated pipeline. Workforce housed in a 44-person camp in Nuuk. Source: user-supplied text (industry/project profile), coordinates as supplied (66.55853N, -52.06692W = 66 33'31"N 52 4'1"W).$c$, modified_by = 'mindat_cleanup_20261125', modified_date = now() WHERE occurrence_id = 3754;
UPDATE core.occurrences SET comments = $c$Kangerluarsuk, West Greenland, ~12 km north of the Black Angel Mine (depositid 14470), within the same Karrat Group formation that hosts Black Angel's mineralisation. COORDINATE FLAG: no coordinates found in any source document despite repeated searches across three separate documents (Amaroq, 80 Mile). Position here is derived by offsetting Black Angel's coordinates ~12 km due north per the stated relative location - not a surveyed or independently sourced point, precision is low. Exploration history: prior operators Cominco, Rio Tinto, and Bluejay Mining (subsequently acquired by/renamed 80 Mile Plc) conducted geophysical and geochemical surveys over a 15 km trend, delineating multiple untested anomalies and high-grade channel sample sites. Project sold by 80 Mile to Amaroq Minerals Ltd in 2025 for US$0.5 million in shares plus US$1.5 million contingent consideration.$c$, modified_by = 'mindat_cleanup_20261125', modified_date = now() WHERE occurrence_id = 3755;
UPDATE core.occurrences SET geom = ST_SetSRID(ST_MakePoint(74.08383, 21.99948), 4326), position_accuracy = NULL, comments = $c$Kawant taluka, Chhota Udepur district, Gujarat. AMD-established resource: 1,120,201 t REO (Rare Earth Elements Oxide) per Department of Atomic Energy reply, Lok Sabha Unstarred Question 1788, 13 Dec 2023. This SUPERSEDES an older AMD figure of 737,283 t REO that circulates in secondary material. The 2025 DAE replies give a combined hard-rock REO resource of 1.29 Mt for Gujarat and Rajasthan. The Ambadungar RE Project has been initiated to harness the carbonatite deposit explored by AMD (Indian Minerals Yearbook 2022, Rare Earths); Gujarat Mineral Development Corporation (GMDC) has also long operated the Ambadungar fluorspar mine in this complex (per GMDC). LOCATION (2026-11-25): point is the USGS MRDS position of the Amba Dongar Fluorspar Deposit (21.9995 N, 74.0838 E, occurrence 402948 in this database), in the same carbonatite complex; a complex-level point, not a deposit outline. The earlier point came from Mindat and was replaced.$c$, modified_by = 'mindat_cleanup_20261125', modified_date = now() WHERE occurrence_id = 3759;
UPDATE core.occurrences SET geom = ST_SetSRID(ST_MakePoint(72.478, 25.785), 4326), position_accuracy = 'AREA_CENTROID', comments = $c$Bhatikhera area, Balotra (formerly Barmer) district, Rajasthan. AMD-established resource: 36,945 t REO per DAE reply, Lok Sabha Unstarred Question 1788, 13 Dec 2023. A news report (Outlook Business, 13 Aug 2025) citing a 2025 parliamentary reply gives a higher figure of 111,845 t REO for Bhati Khera, Siwana; that figure is NOT verified against the primary document and is not loaded as a resource. AMD survey and prospecting continues in the Dantala-Bhatikhera area (same reply). LOCATION (2026-11-25): point computed from the literature description of the deposit as about 18 km N20E of Siwana town (25.785 N, 72.478 E); approximate (+/-3 km), not a deposit outline. A Mindat point and mineral list used in Oct-Nov 2026 were removed.$c$, modified_by = 'mindat_cleanup_20261125', modified_date = now() WHERE occurrence_id = 3760;
UPDATE core.occurrences SET geom = ST_SetSRID(ST_MakePoint(77.33372, 8.20077), 4326), position_accuracy = NULL, comments = $c$Kanniyakumari district, Tamil Nadu. Listed by the Indian Bureau of Mines (Indian Minerals Yearbook 2022, Rare Earths) among the major monazite-bearing deposits; IREL operates a 6,000 tpy monazite separation plant at Manavalakurichi (same source). Monazite resources are published by state only; no per-deposit tonnage or grade is given. LOCATION (2026-11-25): point is the USGS MRDS position of the Manavalakurichi Deposit (8.2008 N, 77.3337 E, occurrence 382027 in this database); approximate, not a deposit outline. The earlier point and mineral list came from Mindat and were removed.$c$, modified_by = 'mindat_cleanup_20261125', modified_date = now() WHERE occurrence_id = 3762;
UPDATE core.occurrences SET geom = ST_SetSRID(ST_MakePoint(85.65, 19.8), 4326), position_accuracy = 'TOWN_CENTROID', comments = $c$Puri district, Odisha. Listed by the Indian Bureau of Mines (Indian Minerals Yearbook 2022, Rare Earths) among the major monazite-bearing deposits; IREL is pursuing greenfield operations in the Brahmagiri area (same source). No per-deposit tonnage or grade is given. LOCATION (2026-11-25): the Indian Minerals Yearbook (Ilmenite and Rutile) describes the Brahmagiri deposit as a coastal strip about 30 km long and 1.9 km wide from Girala nala to Bhabunia villages, Puri district. No published point was found; the point is Brahmagiri town (19.80 N, 85.65 E, GeoNames 1275212, CC BY 4.0), inland of the strip, so treat as +/-15 km. The earlier point and mineral list came from Mindat and were removed.$c$, modified_by = 'mindat_cleanup_20261125', modified_date = now() WHERE occurrence_id = 3772;
UPDATE core.occurrences SET geom = ST_SetSRID(ST_MakePoint(103.55, 22.31), 4326), position_accuracy = NULL, comments = $c$ADDED 2026-10-07 (SDSG batch 3). Facts (owner, stage, deposit style, resource or reserve figures) are from the SDSG Global Inventory of Advanced Rare Earth Element Assets (Gulley and Lederer, Sep 2026, data to Apr 2026; library doc 55), a second-hand secondary source footnoted to company or government reports; verify against the primary report before relying on a figure. Owner Lai Chau-Vimico Rare Earth JSC (Lavreco), a Vimico/Vinacomin subsidiary, Lai Chau Province, Vietnam. Reported reserves of 11.3 million tons of REO (category not stated). The 2023 master plan targets 2 Mt/yr of ore, but in 2025 Vimico reported multi-year difficulties with processing technology, market conditions, capital and partners, and the project lacks regulatory approval, hence status EXPLORATION. LOCATION (2026-11-25): point is the USGS Indo-Pacific mineral facilities compilation position of the Dong Pao Rare Earth Mine (22.31 N, 103.55 E, occurrence 1225728 in this database); treat as +/-5 km. The earlier point came from Mindat and was replaced. Resource and reserve rows in core.resource_estimates (where present) carry blank effective dates because SDSG does not give them.$c$, modified_by = 'mindat_cleanup_20261125', modified_date = now() WHERE occurrence_id = 3827;
REVOKE ALL ON ALL TABLES IN SCHEMA licence_hold FROM PUBLIC;
REVOKE ALL ON ALL TABLES IN SCHEMA licence_hold FROM cm_app_readonly;
COMMIT;
